    public static GUPPriceMarginComponentSetup findByName(GUPPriceComponentCodeName _priceComponentCodeName, boolean _update = false)
    {
        GUPPriceMarginComponentSetup         priceMarginCompSetup;

        if(_update)
        {
            priceMarginCompSetup.selectForUpdate(_update);
        }

        select firstonly priceMarginCompSetup
            where priceMarginCompSetup.PriceComponentCodeName == _priceComponentCodeName;

        return priceMarginCompSetup;
    }

public display Description priceComponentCodeDescription()
{
    return this.priceComponentCode().Description;
}

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(GUPPriceMarginComponentSetup, PostInLedger):
                if (this.PostInLedger == NoYes::Yes)
                {
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, PostingProfile)).mandatory(true);
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, PostingProfile)).allowEdit(true);
                }
                else
                {
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, PostingProfile)).mandatory(false);
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, PostingProfile)).allowEdit(false);
                    this.PostingProfile = 0;
                }
                break;
            case fieldNum(GUPPriceMarginComponentSetup, Flexible):
                if (this.Flexible == NoYes::Yes)
                {
                    this.CalculationSequence = 0;
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CalculationSequence)).mandatory(false);
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CalculationSequence)).allowEdit(false);

                    this.CompoundcalculationBasis = NoYes::No;
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CompoundcalculationBasis)).allowEdit(false);
                }
                else
                {
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CalculationSequence)).mandatory(true);
                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CalculationSequence)).allowEdit(true);

                    this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CompoundcalculationBasis)).allowEdit(true);
                }
                break;
            case fieldNum(GUPPriceMarginComponentSetup, CalculationSequence):
                this.validateCalculationSequence();
                break;
        }
    }

    public void initValue()
    {
        
        super();
        
        FormObjectSet formObjectSet = this.dataSource();
        
        if  (formObjectSet != null)
        {
            this.PostInLedger = NoYes::No;
            this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, PostingProfile)).mandatory(false);
            this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, PostingProfile)).allowEdit(false);

            this.Flexible = NoYes::No;
            this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CalculationSequence)).mandatory(true);
            this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CalculationSequence)).allowEdit(true);
            this.dataSource().object(fieldNum(GUPPriceMarginComponentSetup, CompoundcalculationBasis)).allowEdit(true);
        }
    }

public static boolean existCalcSequence(GUPCalculationSequenceNum _calcSequence)
{
    return (select firstonly CalculationSequence from GUPPriceMarginComponentSetup
               where GUPPriceMarginComponentSetup.CalculationSequence == _calcSequence).CalculationSequence;
}

    public boolean validateCalculationSequence()
    {
        GUPPriceMarginComponentSetup priceMarginComponentSetup;
        boolean isEqual;
        boolean ret = true;

        if (this.Flexible == NoYes::No)
        {
            select firstonly RecId from priceMarginComponentSetup
                where priceMarginComponentSetup.CalculationSequence == this.CalculationSequence
                    && priceMarginComponentSetup.RecId != this.RecId;

            if (priceMarginComponentSetup.RecId)
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPCalculationCompoundError", this.CalculationSequence));
            }
        }

        return ret;
    }

    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (ret)
        {
            if (this.PostInLedger == NoYes::No && this.PostingProfile)
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPPostingProfileValidation", this.PostingProfile, this.PostInLedger));
            }

            if (this.Flexible == NoYes::Yes)
            {
                if (this.CalculationSequence)
                {
                    ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPCalculationSequenceValidation'", this.Flexible));
                }

                if (this.CompoundcalculationBasis)
                {
                    ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPCompoundCalculationBasisValidation", this.Flexible));
                }
            }
            else
            {
                ret = this.validateCalculationSequence();
            }
        }

        return ret;
    }
